public class ChunkSummer {

    public static int[] chunkSums(int[] a, int size) {
        int chunks = (a.length + size - 1) / size;
        int[] result = new int[chunks];
        for (int c = 0; c < chunks; c++) {
            int start = c * size;
            int end = Math.min(start + size, a.length);
            int sum = 0;
            for (int i = start; i < end; i++) {
                sum += a[i];
            }
            result[c] = sum;
        }
        return result;
    }
}
